{"title":"Stellar Murmuration","code":"let boids = [];
let numBoids = 600;

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 1);
  for (let i = 0; i < numBoids; i++) {
    boids.push(new Boid(random(width), random(height)));
  }
}

function draw() {
  let bgCol = color(params.bgColor);
  bgCol.setAlpha(0.25);
  background(bgCol);

  let center = createVector(width / 2, height / 2 + 50);

  // Draw invisible lighthouse aura / beacon
  if (params.showBeacon) {
    push();
    noStroke();
    let beaconCol = color(params.boidColor);
    beaconCol.setAlpha(0.05);
    fill(beaconCol);
    ellipse(center.x, center.y - 100, 150 * params.scale, 400 * params.scale);
    pop();
  }

  let maxCount = floor(map(params.population, 0, 100, 50, numBoids));

  for (let i = 0; i < maxCount; i++) {
    let b = boids[i];
    b.update(center);
    b.show();
  }
}

class Boid {
  constructor(x, y) {
    this.pos = createVector(x, y);
    this.vel = p5.Vector.random2D().mult(random(2, 4));
    this.acc = createVector(0, 0);
    this.maxSpeed = 4;
    this.maxForce = 0.2;
    this.size = random(2, 5);
  }

  update(target) {
    let s = params.speed;

    // Spiral force around lighthouse center
    let toCenter = p5.Vector.sub(target, this.pos);
    let distToCenter = toCenter.mag();
    toCenter.normalize();

    // Tangent vector for swirling
    let tangent = createVector(-toCenter.y, toCenter.x);

    let pullForce = toCenter.mult(map(distToCenter, 0, width, 0.1, 0.8) * params.pullStrength);
    let swirlForce = tangent.mult(2.5 * params.speed);

    // Mouse interaction
    let mouse = createVector(mouseX, mouseY);
    let dMouse = p5.Vector.dist(this.pos, mouse);
    if (dMouse < 150 && mouseX > 0 && mouseY > 0) {
      let flee = p5.Vector.sub(this.pos, mouse);
      flee.normalize();
      flee.mult(5);
      this.acc.add(flee);
    }

    this.acc.add(pullForce);
    this.acc.add(swirlForce);

    // Turbulence via noise
    let n = noise(this.pos.x * 0.005, this.pos.y * 0.005, frameCount * 0.01 * s);
    let angle = n * TWO_PI * 2;
    let noiseForce = p5.Vector.fromAngle(angle).mult(1.5);
    this.acc.add(noiseForce);

    this.vel.add(this.acc);
    this.vel.limit(this.maxSpeed * s);
    this.pos.add(this.vel);
    this.acc.mult(0);

    // Wrap borders gently
    if (this.pos.x < -50) this.pos.x = width + 50;
    if (this.pos.x > width + 50) this.pos.x = -50;
    if (this.pos.y < -50) this.pos.y = height + 50;
    if (this.pos.y > height + 50) this.pos.y = -50;
  }

  show() {
    push();
    noStroke();
    let c = color(params.boidColor);
    fill(c);

    // Draw bird as a small oriented triangle/ellipse
    let theta = this.vel.heading() + PI / 2;
    translate(this.pos.x, this.pos.y);
    rotate(theta);

    beginShape();
    vertex(0, -this.size * params.scale);
    vertex(-this.size * 0.7 * params.scale, this.size * params.scale);
    vertex(this.size * 0.7 * params.scale, this.size * params.scale);
    endShape(CLOSE);
    pop();
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
