  "title": "Milk Ink Plume",
  "code": "let particles = [];

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 100);

  // Initialize maximum possible particles
  for (let i = 0; i < 1500; i++) {
    particles.push(new InkParticle());
  }
}

function draw() {
  // Milk background with slight persistence for motion blur
  let bgCol = color(params.milkHue, 15, 95);
  background(hue(bgCol), saturation(bgCol), brightness(bgCol), 15);

  let count = floor(params.particleCount);
  let t = millis() * 0.0005 * params.speed;

  let mainColor;
  if (params.inkColor === "Indigo") {
    mainColor = color(240, 80, 20, 25);
  } else if (params.inkColor === "Crimson") {
    mainColor = color(350, 90, 60, 25);
  } else if (params.inkColor === "Emerald") {
    mainColor = color(150, 80, 50, 25);
  } else {
    mainColor = color(280, 85, 45, 25);
  }

  for (let i = 0; i < count; i++) {
    let p = particles[i];
    p.update(t, params.turbulence, params.speed);
    p.display(mainColor);
  }
}

class InkParticle {
  constructor() {
    this.reset(true);
  }

  reset(initial = false) {
    this.x = width * 0.5 + random(-40, 40);
    this.y = initial ? random(height * 0.2, height * 0.9) : height + random(10, 50);
    this.vx = 0;
    this.vy = random(-2, -0.5);
    this.age = 0;
    this.lifeSpan = random(200, 450);
    this.size = random(2, 12);
  }

  update(t, turb, spd) {
    let nScale = 0.003 * turb;
    let angle = noise(this.x * nScale, this.y * nScale, t) * TWO_PI * 4;

    // Flow field force combined with upward buoyancy and curl
    let fx = cos(angle) * 0.8;
    let fy = sin(angle) * 0.8 - (0.4 * params.buoyancy);

    this.vx += fx * 0.1;
    this.vy += fy * 0.1;

    // Damping
    this.vx *= 0.94;
    this.vy *= 0.94;

    this.x += this.vx * spd;
    this.y += this.vy * spd;

    // Gentle horizontal pull towards center to keep plume bounded
    let centerPull = (width * 0.5 - this.x) * 0.0002;
    this.x += centerPull;

    this.age++;
    if (this.age > this.lifeSpan || this.y < -50 || this.x < 0 || this.x > width) {
      this.reset();
    }
  }

  display(baseCol) {
    noStroke();
    let lifeRatio = 1 - (this.age / this.lifeSpan);
    let c = color(
      hue(baseCol),
      saturation(baseCol),
      brightness(baseCol) + (1 - lifeRatio) * 20,
      alpha(baseCol) * lifeRatio
    );
    fill(c);
    ellipse(this.x, this.y, this.size * lifeRatio);
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
