  let s = params.speed;
  flying -= s * 0.05;

  let zOff = flying;
  let terrainWidth = terrainCols * terrainScale;
  let terrainDepth = terrainRows * terrainScale;

  if (params.nightMode) {
    ambientLight(40, 40, 60);
    directionalLight(200, 220, 255, 0.5, 1, -0.5);
    pointLight(255, 100, 150, 0, -300, -200);
  } else {
    ambientLight(150, 150, 150);
    directionalLight(255, 255, 255, 0.5, 1, 0.5);
    pointLight(255, 200, 150, 0, -400, -300);
  }

  push();
  rotateX(QUARTER_PI * 0.9);
  translate(-terrainWidth / 2, -terrainDepth / 2, -100);

  let baseHue = params.palette === 'Neon' ? 300 : (params.palette === 'Sunset' ? 15 : 120);

  let yVals = [];
  for (let y = 0; y < terrainRows; y++) {
    yVals[y] = [];
    let xOff = 0;
    for (let x = 0; x < terrainCols; x++) {
      let h = map(noise(xOff, zOff), 0, 1, -180, 180);
      // Add a valley in the middle
      let distFromCenter = abs(x - terrainCols / 2) / (terrainCols / 2);
      h *= pow(distFromCenter, 0.7);
      yVals[y][x] = h;
      xOff += 0.15;
    }
    zOff += 0.15;
  }

  for (let y = 0; y < terrainRows - 1; y++) {
    beginShape(TRIANGLE_STRIP);
    for (let x = 0; x < terrainCols; x++) {
      let h1 = yVals[y][x];
      let h2 = yVals[y + 1][x];

      let n1 = map(h1, -180, 180, 0, 1);
      let n2 = map(h2, -180, 180, 0, 1);

      if (params.palette === 'Neon') {
        fill(n1 * 255, 50, 250 - n1 * 150);
      } else if (params.palette === 'Sunset') {
        fill(255, n1 * 180, n1 * 50);
      } else {
        fill(40 + n1 * 60, 120 + n1 * 100, 60 + n1 * 40);
      }
      vertex(x * terrainScale, y * terrainScale, h1);

      if (params.palette === 'Neon') {
        fill(n2 * 255, 50, 250 - n2 * 150);
      } else if (params.palette === 'Sunset') {
        fill(255, n2 * 180, n2 * 50);
      } else {
        fill(40 + n2 * 60, 120 + n2 * 100, 60 + n2 * 40);
      }
      vertex(x * terrainScale, (y + 1) * terrainScale, h2);
    }
    endShape();
  }
  pop();
}

