  "title": "Orbital Typography",
  "code": "let font;
let letters = "ORBIT";
let rings = [];

function setup() {
  createCanvas(windowWidth, windowHeight);
  angleMode(RADIANS);
  textAlign(CENTER, CENTER);
  textSize(24);

  // Initialize rings
  for (let i = 0; i < 8; i++) {
    rings.push({
      radius: 60 + i * 45,
      speed: (i % 2 === 0 ? 1 : -1) * (0.2 + i * 0.05),
      offset: random(TWO_PI),
      charIndex: i % letters.length
    });
  }
}

function draw() {
  background(params.bgColor);

  let cx = width / 2;
  let cy = height / 2;

  // Draw central glowing core
  noStroke();
  let c = color(params.accentColor);
  for (let r = 80; r > 0; r -= 10) {
    let alpha = map(r, 0, 80, 80, 0);
    fill(red(c), green(c), blue(c), alpha);
    ellipse(cx, cy, r * 2);
  }

  // Draw orbits and text
  noFill();
  strokeWeight(1);

  let baseSpeed = params.speed;
  let totalRings = floor(params.ringCount);

  for (let i = 0; i < totalRings; i++) {
    // Reuse or create ring data dynamically
    if (i >= rings.length) {
      rings.push({
        radius: 60 + i * 45,
        speed: (i % 2 === 0 ? 1 : -1) * (0.2 + i * 0.05),
        offset: random(TWO_PI),
        charIndex: i % letters.length
      });
    }

    let ring = rings[i];

    // Draw orbit path
    stroke(red(c), green(c), blue(c), 30);
    ellipse(cx, cy, ring.radius * 2);

    // Calculate letter positions along the ring
    let numChars = params.letterCount;
    let angleStep = TWO_PI / numChars;
    let currentAngle = ring.offset + (frameCount * 0.01 * ring.speed * baseSpeed);

    for (let j = 0; j < numChars; j++) {
      let theta = currentAngle + j * angleStep;
      let x = cx + cos(theta) * ring.radius;
      let y = cy + sin(theta) * ring.radius;

      push();
      translate(x, y);
      // Rotate letters to follow the tangent of the circle, plus a slight wiggle
      rotate(theta + HALF_PI);

      let charToShow = letters[(ring.charIndex + j) % letters.length];

      fill(params.textColor);
      noStroke();
      textSize(params.fontSize);
      text(charToShow, 0, 0);
      pop();
    }
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
