  "title": "Elastic Spring Grid",
  "code": "let cols = 30;
let rows = 20;
let nodes = [];

function setup() {
  createCanvas(windowWidth, windowHeight);
  initGrid();
}

function initGrid() {
  nodes = [];
  let dx = width / (cols - 1);
  let dy = height / (rows - 1);
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      let px = x * dx;
      let py = y * dy;
      nodes.push({
        x: px,
        y: py,
        ox: px,
        oy: py,
        vx: 0,
        vy: 0
      });
    }
  }
}

function draw() {
  background(params.bgColor);

  let k = 0.05 * params.stiffness;
  let damp = 0.85;
  let pullRadius = params.radius;
  let pullStrength = params.strength * 2;

  // Update physics
  for (let i = 0; i < nodes.length; i++) {
    let n = nodes[i];

    // Spring force to origin
    let fx = (n.ox - n.x) * k;
    let fy = (n.oy - n.y) * k;

    n.vx = (n.vx + fx) * damp;
    n.vy = (n.vy + fy) * damp;

    // Mouse interaction
    let d = dist(mouseX, mouseY, n.x, n.y);
    if (d < pullRadius && d > 0) {
      let factor = (1.0 - d / pullRadius) * pullStrength;
      if (mouseIsPressed) {
        // Push away on click
        n.vx -= (mouseX - n.x) / d * factor * 5;
        n.vy -= (mouseY - n.y) / d * factor * 5;
      } else {
        // Pull towards mouse
        n.vx += (mouseX - n.x) / d * factor;
        n.vy += (mouseY - n.y) / d * factor;
      }
    }

    n.x += n.vx * params.speed;
    n.y += n.vy * params.speed;
  }

  // Draw grid lines
  stroke(params.gridColor);
  strokeWeight(1.5);
  noFill();

  // Horizontal lines
  for (let y = 0; y < rows; y++) {
    beginShape();
    for (let x = 0; x < cols; x++) {
      let n = nodes[y * cols + x];
      vertex(n.x, n.y);
    }
    endShape();
  }

  // Vertical lines
  for (let x = 0; x < cols; x++) {
    beginShape();
    for (let y = 0; y < rows; y++) {
      let n = nodes[y * cols + x];
      vertex(n.x, n.y);
    }
    endShape();
  }

  // Draw nodes
  noStroke();
  fill(params.nodeColor);
  let nodeSize = params.nodeSize;
  if (nodeSize > 0) {
    for (let i = 0; i < nodes.length; i++) {
      let n = nodes[i];
      ellipse(n.x, n.y, nodeSize, nodeSize);
    }
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  initGrid();
