{"title":"Monochrome Op-Art Twister","code":"let angle = 0;
function setup() {
  createCanvas(windowWidth, windowHeight);
  rectMode(CENTER);
}
function draw() {
  background(params.invert ? 255 : 0);
  let cols = params.gridSize;
  let rows = params.gridSize;
  let w = width / cols;
  let h = height / rows;

  angle += params.speed * 0.01;

  let maxDist = dist(0, 0, width/2, height/2);

  for (let i = 0; i < cols; i++) {
    for (let j = 0; j < rows; j++) {
      let x = w * i + w / 2;
      let y = h * j + h / 2;

      let d = dist(x, y, width / 2, height / 2);
      let offset = map(d, 0, maxDist, 0, TWO_PI * params.twist);
      let currentAngle = angle + offset;

      let bFactor = sin(frameCount * 0.03 * params.breathe + d * 0.005);
      let sizeFactor = map(bFactor, -1, 1, 0.4, 1.4);

      push();
      translate(x, y);
      rotate(currentAngle);

      let isDark = (i + j) % 2 === 0;
      if (params.invert) isDark = !isDark;

      fill(isDark ? 0 : 255);
      noStroke();

      rect(0, 0, w * sizeFactor * params.scaleSize, h * sizeFactor * params.scaleSize);
      pop();
    }
  }
}
